    @php($deadline = $deadlines[$order->slug])
    <article class="operations-order" data-operation-order="{{ $order->slug }}">
        <header><a href="{{ route('orders.show', $order) }}"><strong>{{ $order->reference }}</strong><span>{{ $order->recipient_name }}</span></a><x-ui.status-badge :status="$order->status" />
        @if($deadline['overdue'] || $deadline['delivered_late'])<details class="delivery-late"><summary aria-label="{{ $deadline['overdue'] ? 'Consegna in ritardo' : 'Consegnata oltre il termine previsto' }}"><x-ui.icon name="info-circle-fill" /></summary><div role="note"><strong>{{ $deadline['overdue'] ? 'Consegna in ritardo' : 'Consegnata oltre il termine previsto' }}</strong><p>{{ $deadline['overdue'] ? 'La spedizione non è stata ancora completata ed è stato superato il termine di consegna previsto.' : 'La consegna è stata completata dopo la scadenza prevista.' }}</p><dl><div><dt>Termine previsto</dt><dd>{{ $deadline['label'] }}</dd></div>@if($deadline['elapsed'])<div><dt>Tempo oltre il termine</dt><dd>{{ $deadline['elapsed'] }}</dd></div>@endif<div><dt>Rider assegnato</dt><dd>{{ $order->rider?->name ?: 'Da assegnare' }}</dd></div><div><dt>Stato corrente</dt><dd>{{ $order->status->label() }}</dd></div></dl></div></details>@endif</header>
        <p>{{ $order->displayName() }} · {{ $order->pickup_city }} → {{ $order->delivery_city }}</p>
        <dl><div><dt>Programmata</dt><dd>{{ $order->pickup_date->format('d/m/Y') }}</dd></div><div><dt>Rider</dt><dd>{{ $order->rider?->name ?: 'Da assegnare' }}</dd></div><div><dt>Consegna effettiva</dt><dd>{{ $order->delivered_at?->timezone('Europe/Rome')->format('d/m/Y H:i') ?: 'Non registrata' }}</dd></div><div><dt>Tariffa</dt><dd>{{ \App\Support\Money::format($order->price_cents) }}</dd></div></dl>
        @if($order->shipping_type === 'external')<p class="small text-secondary">Spedizione fuori regione · quote EA e vettore distinte nel registro.</p>@endif
        @if($showPayments ?? false)<details class="rider-payment-ledger"><summary>Incassi, rettifiche e storni registrati</summary>@forelse($order->payments as $payment)<p><time>{{ $payment->created_at->timezone('Europe/Rome')->format('d/m/Y H:i:s') }}</time><span>{{ $payment->note ?: 'Movimento registrato' }} · {{ $payment->user?->name }}</span><strong>{{ \App\Support\Money::format($payment->amount_cents) }}</strong><small>EA: {{ \App\Support\Money::format($payment->ea_amount_cents ?? $payment->amount_cents) }}</small></p>@empty<p class="small text-secondary">Nessun incasso registrato.</p>@endforelse<a href="{{ route('audits.index',['type'=>'orders','slug'=>$order->slug]) }}">Storico rettifiche ordine</a></details>@endif
    </article>
